'use client';

// FILE: p2p-kids-admin/src/app/categories/components/CategorySuggestionsList.tsx
// ADMIN-V3-005: Category Suggestions List with Approve/Merge/Reject actions
// Module: MODULE-12-ADMIN-V3-CATEGORIES

import { useState, useEffect } from 'react';
import { ExternalLink, CheckCircle, GitMerge, XCircle } from 'lucide-react';
import type { CategorySuggestion } from '../../../types/category';
import { getCategorySuggestions } from '../../../lib/categorySuggestionService';
import { ApproveSuggestionModal } from './ApproveSuggestionModal';
import { MergeSuggestionModal } from './MergeSuggestionModal';
import { RejectSuggestionModal } from './RejectSuggestionModal';

interface CategorySuggestionsListProps {
  onCountChange?: (count: number) => void;
}

export function CategorySuggestionsList({ onCountChange }: CategorySuggestionsListProps) {
  const [suggestions, setSuggestions] = useState<CategorySuggestion[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Modal state
  const [approveModalOpen, setApproveModalOpen] = useState(false);
  const [mergeModalOpen, setMergeModalOpen] = useState(false);
  const [rejectModalOpen, setRejectModalOpen] = useState(false);
  const [selectedSuggestion, setSelectedSuggestion] = useState<CategorySuggestion | null>(null);

  useEffect(() => {
    loadSuggestions();
  }, []);

  const loadSuggestions = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await getCategorySuggestions('pending', true);
      setSuggestions(data);
      onCountChange?.(data.length);
    } catch (err: any) {
      console.error('Error loading suggestions:', err);
      setError(err.message || 'Failed to load suggestions');
    } finally {
      setLoading(false);
    }
  };

  const handleApproveClick = (suggestion: CategorySuggestion) => {
    setSelectedSuggestion(suggestion);
    setApproveModalOpen(true);
  };

  const handleMergeClick = (suggestion: CategorySuggestion) => {
    setSelectedSuggestion(suggestion);
    setMergeModalOpen(true);
  };

  const handleRejectClick = (suggestion: CategorySuggestion) => {
    setSelectedSuggestion(suggestion);
    setRejectModalOpen(true);
  };

  const handleActionSuccess = (message: string) => {
    setSuccessMessage(message);
    setTimeout(() => setSuccessMessage(null), 4000);
    loadSuggestions(); // Refresh list
  };

  const formatDate = (isoDate: string): string => {
    const date = new Date(isoDate);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffDays === 0) {
      const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
      if (diffHours === 0) {
        const diffMinutes = Math.floor(diffMs / (1000 * 60));
        return diffMinutes <= 1 ? 'Just now' : `${diffMinutes} minutes ago`;
      }
      return diffHours === 1 ? '1 hour ago' : `${diffHours} hours ago`;
    }

    if (diffDays === 1) return 'Yesterday';
    if (diffDays < 7) return `${diffDays} days ago`;
    return date.toLocaleDateString();
  };

  if (loading) {
    return (
      <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
        <p className="text-gray-600" data-testid="suggestions-loading">
          Loading suggestions...
        </p>
      </div>
    );
  }

  if (error) {
    return (
      <div
        className="bg-red-50 border border-red-200 rounded-md p-4"
        data-testid="suggestions-error"
      >
        <p className="text-sm text-red-800">{error}</p>
      </div>
    );
  }

  if (suggestions.length === 0) {
    return (
      <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
        <p className="text-gray-600" data-testid="suggestions-empty">
          No pending category suggestions. Suggestions appear when sellers select "Other" and
          provide a custom category name.
        </p>
      </div>
    );
  }

  return (
    <>
      {/* Success Message */}
      {successMessage && (
        <div
          className="mb-4 p-4 bg-green-50 border border-green-200 rounded-md"
          data-testid="suggestions-success"
        >
          <p className="text-sm text-green-800">{successMessage}</p>
        </div>
      )}

      {/* Table */}
      <div className="bg-white shadow-sm rounded-lg border border-gray-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200" data-testid="suggestions-table">
            <thead className="bg-gray-50">
              <tr>
                <th
                  scope="col"
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                >
                  Suggested Name
                </th>
                <th
                  scope="col"
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                >
                  Item
                </th>
                <th
                  scope="col"
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                >
                  Seller
                </th>
                <th
                  scope="col"
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                >
                  Date
                </th>
                <th
                  scope="col"
                  className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider"
                >
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {suggestions.map((suggestion) => (
                <tr
                  key={suggestion.id}
                  className="hover:bg-gray-50 transition-colors"
                  data-testid={`suggestion-row-${suggestion.id}`}
                >
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-gray-900">
                      {suggestion.suggested_name}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {suggestion.item ? (
                      <a
                        href={`/items/${suggestion.item_id}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center text-sm text-blue-600 hover:text-blue-800"
                        data-testid={`item-link-${suggestion.id}`}
                      >
                        <span className="max-w-xs truncate">{suggestion.item.name}</span>
                        <ExternalLink size={14} className="ml-1 flex-shrink-0" />
                      </a>
                    ) : (
                      <span className="text-sm text-gray-400">N/A</span>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {suggestion.seller ? (
                      <div className="text-sm">
                        <div className="font-medium text-gray-900">
                          {suggestion.seller.full_name || 'Unknown'}
                        </div>
                        <div className="text-gray-500 text-xs">
                          {suggestion.seller.email?.substring(0, 20)}
                          {(suggestion.seller.email?.length || 0) > 20 ? '...' : ''}
                        </div>
                      </div>
                    ) : (
                      <span className="text-sm text-gray-400">N/A</span>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm text-gray-600">{formatDate(suggestion.created_at)}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <div className="flex items-center justify-end gap-2">
                      <button
                        onClick={() => handleApproveClick(suggestion)}
                        data-testid={`approve-btn-${suggestion.id}`}
                        className="inline-flex items-center px-3 py-1.5 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors"
                        title="Approve and create new category"
                      >
                        <CheckCircle size={16} className="mr-1" />
                        Approve
                      </button>
                      <button
                        onClick={() => handleMergeClick(suggestion)}
                        data-testid={`merge-btn-${suggestion.id}`}
                        className="inline-flex items-center px-3 py-1.5 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors"
                        title="Merge into existing category"
                      >
                        <GitMerge size={16} className="mr-1" />
                        Merge
                      </button>
                      <button
                        onClick={() => handleRejectClick(suggestion)}
                        data-testid={`reject-btn-${suggestion.id}`}
                        className="inline-flex items-center px-3 py-1.5 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors"
                        title="Reject suggestion"
                      >
                        <XCircle size={16} className="mr-1" />
                        Reject
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modals */}
      {selectedSuggestion && (
        <>
          {approveModalOpen && (
            <ApproveSuggestionModal
              suggestion={selectedSuggestion}
              onClose={() => {
                setApproveModalOpen(false);
                setSelectedSuggestion(null);
              }}
              onSuccess={handleActionSuccess}
            />
          )}
          {mergeModalOpen && (
            <MergeSuggestionModal
              suggestion={selectedSuggestion}
              onClose={() => {
                setMergeModalOpen(false);
                setSelectedSuggestion(null);
              }}
              onSuccess={handleActionSuccess}
            />
          )}
          {rejectModalOpen && (
            <RejectSuggestionModal
              suggestion={selectedSuggestion}
              onClose={() => {
                setRejectModalOpen(false);
                setSelectedSuggestion(null);
              }}
              onSuccess={handleActionSuccess}
            />
          )}
        </>
      )}
    </>
  );
}

'use client';

// FILE: p2p-kids-admin/src/app/categories/components/ApproveSuggestionModal.tsx
// ADMIN-V3-005: Approve suggestion modal (re-uses CategoryForm)
// Module: MODULE-12-ADMIN-V3-CATEGORIES

import { useState } from 'react';
import { X } from 'lucide-react';
import type { CategorySuggestion, CreateCategoryInput } from '../../../types/category';
import { approveCategorySuggestion } from '../../../lib/categorySuggestionService';
import { CategoryForm } from './CategoryForm';

interface ApproveSuggestionModalProps {
  suggestion: CategorySuggestion;
  onClose: () => void;
  onSuccess: (message: string) => void;
}

export function ApproveSuggestionModal({
  suggestion,
  onClose,
  onSuccess,
}: ApproveSuggestionModalProps) {
  const [showForm, setShowForm] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFormSuccess = async (categoryData: CreateCategoryInput) => {
    try {
      setSubmitting(true);
      setError(null);

      // Get current admin user ID from session/auth
      // TODO: Replace with actual auth context
      const adminUserId = 'temp-admin-id'; // Placeholder

      await approveCategorySuggestion(
        suggestion.id,
        {
          categoryData,
          reassignItem: true, // Always reassign the item to the new category
        },
        adminUserId
      );

      onSuccess(
        `Category "${categoryData.name}" created and item reassigned successfully`
      );
      onClose();
    } catch (err: any) {
      console.error('Error approving suggestion:', err);
      setError(err.message || 'Failed to approve suggestion');
      setSubmitting(false);
    }
  };

  const handleFormClose = () => {
    if (submitting) return; // Prevent closing while submitting
    onClose();
  };

  // Prepare pre-filled category data
  const preFillData = {
    name: suggestion.suggested_name,
    description: null,
    icon: null,
    icon_url: null,
    bonus_badge_icon_url: null,
    is_active: true, // Default to active
    sp_earning_multiplier: 1.10, // Default
    sp_spending_cap_percent: 70, // Default
    sp_config_notes: null,
  };

  return (
    <div
      className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50"
      onClick={handleFormClose}
      data-testid="approve-modal-overlay"
    >
      <div
        className="bg-white rounded-lg shadow-xl w-full max-w-3xl max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-labelledby="approve-modal-title"
      >
        {/* Header */}
        <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between z-10">
          <div>
            <h2
              id="approve-modal-title"
              className="text-xl font-semibold text-gray-900"
              data-testid="approve-modal-title"
            >
              Approve Category Suggestion
            </h2>
            <p className="mt-1 text-sm text-gray-600">
              Review and customize the category before approval. The item will be automatically
              reassigned to the new category.
            </p>
          </div>
          <button
            onClick={handleFormClose}
            disabled={submitting}
            data-testid="approve-modal-close"
            className="text-gray-400 hover:text-gray-600 transition-colors disabled:opacity-50"
            aria-label="Close modal"
          >
            <X size={24} />
          </button>
        </div>

        {/* Error Message */}
        {error && (
          <div
            className="mx-6 mt-4 p-4 bg-red-50 border border-red-200 rounded-md"
            data-testid="approve-modal-error"
          >
            <p className="text-sm text-red-800">{error}</p>
          </div>
        )}

        {/* Info Card */}
        <div className="mx-6 mt-4 p-4 bg-blue-50 border border-blue-200 rounded-md">
          <p className="text-sm text-blue-800">
            <strong>Suggestion from:</strong>{' '}
            {suggestion.seller?.full_name || suggestion.seller?.email || 'Unknown'}
            <br />
            <strong>Item:</strong> {suggestion.item?.name || 'Unknown'} (ID: {suggestion.item_id}
            )
            <br />
            <strong>Suggested name:</strong> {suggestion.suggested_name}
          </p>
        </div>

        {/* Embedded CategoryForm */}
        {showForm && (
          <div className="p-6">
            <CategoryFormWrapper
              preFillData={preFillData}
              onSubmit={handleFormSuccess}
              onCancel={handleFormClose}
              submitting={submitting}
            />
          </div>
        )}
      </div>
    </div>
  );
}

// Wrapper component that uses CategoryForm's internal logic but custom submit
interface CategoryFormWrapperProps {
  preFillData: CreateCategoryInput;
  onSubmit: (data: CreateCategoryInput) => Promise<void>;
  onCancel: () => void;
  submitting: boolean;
}

function CategoryFormWrapper({
  preFillData,
  onSubmit,
  onCancel,
  submitting,
}: CategoryFormWrapperProps) {
  const [formData, setFormData] = useState<CreateCategoryInput>(preFillData);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleInputChange = (field: keyof CreateCategoryInput, value: any) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    // Clear error for this field
    setErrors((prev) => ({ ...prev, [field]: '' }));
  };

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!formData.name || formData.name.trim().length === 0) {
      newErrors.name = 'Name is required';
    } else if (formData.name.length < 3 || formData.name.length > 50) {
      newErrors.name = 'Name must be 3-50 characters';
    } else if (!/^[A-Za-z0-9 ]{3,50}$/.test(formData.name)) {
      newErrors.name = 'Name can only contain letters, numbers, and spaces';
    }

    if (formData.description && formData.description.length > 200) {
      newErrors.description = 'Description must be 200 characters or less';
    }

    if (
      formData.sp_earning_multiplier &&
      (formData.sp_earning_multiplier < 1.05 || formData.sp_earning_multiplier > 1.4)
    ) {
      newErrors.sp_earning_multiplier = 'Must be between 1.05 and 1.40';
    }

    if (
      formData.sp_spending_cap_percent &&
      (formData.sp_spending_cap_percent < 50 || formData.sp_spending_cap_percent > 80)
    ) {
      newErrors.sp_spending_cap_percent = 'Must be between 50 and 80';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;
    await onSubmit(formData);
  };

  return (
    <form onSubmit={handleSubmit} data-testid="approve-form">
      {/* Basic Info Section */}
      <div className="space-y-4">
        <h3 className="text-lg font-medium text-gray-900">Category Details</h3>

        {/* Name */}
        <div>
          <label
            htmlFor="category-name"
            className="block text-sm font-medium text-gray-700 mb-1"
          >
            Name <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            id="category-name"
            value={formData.name}
            onChange={(e) => handleInputChange('name', e.target.value)}
            data-testid="approve-form-name"
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 ${
              errors.name
                ? 'border-red-300 focus:ring-red-500'
                : 'border-gray-300 focus:ring-blue-500'
            }`}
            maxLength={50}
          />
          {errors.name && (
            <p className="mt-1 text-sm text-red-600" data-testid="name-error">
              {errors.name}
            </p>
          )}
        </div>

        {/* Description */}
        <div>
          <label
            htmlFor="category-description"
            className="block text-sm font-medium text-gray-700 mb-1"
          >
            Description (optional)
          </label>
          <textarea
            id="category-description"
            value={formData.description || ''}
            onChange={(e) => handleInputChange('description', e.target.value)}
            data-testid="approve-form-description"
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 ${
              errors.description
                ? 'border-red-300 focus:ring-red-500'
                : 'border-gray-300 focus:ring-blue-500'
            }`}
            rows={3}
            maxLength={200}
          />
          <p className="mt-1 text-xs text-gray-500">
            {(formData.description || '').length}/200 characters
          </p>
          {errors.description && (
            <p className="mt-1 text-sm text-red-600">{errors.description}</p>
          )}
        </div>

        {/* Active Toggle */}
        <div className="flex items-center">
          <input
            type="checkbox"
            id="category-active"
            checked={formData.is_active ?? true}
            onChange={(e) => handleInputChange('is_active', e.target.checked)}
            data-testid="approve-form-active"
            className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
          />
          <label htmlFor="category-active" className="ml-2 text-sm text-gray-700">
            Active (visible to buyers)
          </label>
        </div>
      </div>

      {/* Actions */}
      <div className="mt-6 flex items-center justify-end gap-3 pt-4 border-t border-gray-200">
        <button
          type="button"
          onClick={onCancel}
          disabled={submitting}
          data-testid="approve-form-cancel"
          className="px-4 py-2 border border-gray-300 rounded-md text-gray-700 hover:bg-gray-50 transition-colors disabled:opacity-50"
        >
          Cancel
        </button>
        <button
          type="submit"
          disabled={submitting}
          data-testid="approve-form-submit"
          className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors disabled:opacity-50"
        >
          {submitting ? 'Creating...' : 'Approve & Create Category'}
        </button>
      </div>
    </form>
  );
}

'use client';

// FILE: p2p-kids-admin/src/app/categories/components/MergeSuggestionModal.tsx
// ADMIN-V3-005: Merge suggestion modal (dropdown of existing categories)
// Module: MODULE-12-ADMIN-V3-CATEGORIES

import { useState, useEffect } from 'react';
import { X } from 'lucide-react';
import type { CategorySuggestion, Category } from '../../../types/category';
import { getCategories } from '../../../lib/categoryService';
import { mergeCategorySuggestion } from '../../../lib/categorySuggestionService';

interface MergeSuggestionModalProps {
  suggestion: CategorySuggestion;
  onClose: () => void;
  onSuccess: (message: string) => void;
}

export function MergeSuggestionModal({
  suggestion,
  onClose,
  onSuccess,
}: MergeSuggestionModalProps) {
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedCategoryId, setSelectedCategoryId] = useState<string>('');
  const [adminNote, setAdminNote] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadCategories();
  }, []);

  const loadCategories = async () => {
    try {
      setLoading(true);
      const data = await getCategories(false); // Only active categories
      setCategories(data.filter((c) => c.is_active)); // Double-check active filter
    } catch (err: any) {
      console.error('Error loading categories:', err);
      setError(err.message || 'Failed to load categories');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedCategoryId) {
      setError('Please select a category');
      return;
    }

    try {
      setSubmitting(true);
      setError(null);

      // Get current admin user ID from session/auth
      // TODO: Replace with actual auth context
      const adminUserId = 'temp-admin-id'; // Placeholder

      await mergeCategorySuggestion(
        suggestion.id,
        {
          target_category_id: selectedCategoryId,
          admin_note: adminNote.trim() || null,
        },
        adminUserId
      );

      const selectedCategory = categories.find((c) => c.id === selectedCategoryId);
      onSuccess(
        `Suggestion merged into "${selectedCategory?.name || 'category'}" successfully`
      );
      onClose();
    } catch (err: any) {
      console.error('Error merging suggestion:', err);
      setError(err.message || 'Failed to merge suggestion');
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    if (submitting) return; // Prevent closing while submitting
    onClose();
  };

  return (
    <div
      className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50"
      onClick={handleClose}
      data-testid="merge-modal-overlay"
    >
      <div
        className="bg-white rounded-lg shadow-xl w-full max-w-lg"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-labelledby="merge-modal-title"
      >
        {/* Header */}
        <div className="border-b border-gray-200 px-6 py-4 flex items-center justify-between">
          <h2
            id="merge-modal-title"
            className="text-xl font-semibold text-gray-900"
            data-testid="merge-modal-title"
          >
            Merge Into Existing Category
          </h2>
          <button
            onClick={handleClose}
            disabled={submitting}
            data-testid="merge-modal-close"
            className="text-gray-400 hover:text-gray-600 transition-colors disabled:opacity-50"
            aria-label="Close modal"
          >
            <X size={24} />
          </button>
        </div>

        {/* Content */}
        <form onSubmit={handleSubmit} data-testid="merge-form">
          <div className="px-6 py-4 space-y-4">
            {/* Info Card */}
            <div className="p-4 bg-blue-50 border border-blue-200 rounded-md">
              <p className="text-sm text-blue-800">
                <strong>Suggestion:</strong> {suggestion.suggested_name}
                <br />
                <strong>Item:</strong> {suggestion.item?.name || 'Unknown'}
                <br />
                This will reassign the item to the selected existing category.
              </p>
            </div>

            {/* Error Message */}
            {error && (
              <div
                className="p-4 bg-red-50 border border-red-200 rounded-md"
                data-testid="merge-modal-error"
              >
                <p className="text-sm text-red-800">{error}</p>
              </div>
            )}

            {/* Category Dropdown */}
            <div>
              <label
                htmlFor="merge-category"
                className="block text-sm font-medium text-gray-700 mb-1"
              >
                Select Existing Category <span className="text-red-500">*</span>
              </label>
              {loading ? (
                <div className="text-sm text-gray-500">Loading categories...</div>
              ) : categories.length === 0 ? (
                <div className="text-sm text-red-600">
                  No active categories available. Please create a category first.
                </div>
              ) : (
