}

async function resolveAdminUserId(
  supabase: any,
  adminUserId?: string
): Promise<string | null> {
  if (adminUserId && UUID_REGEX.test(adminUserId)) {
    return adminUserId;
  }

  try {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    return user?.id || null;
  } catch (error) {
    console.warn('[categorySuggestionService] Could not resolve admin user from session:', error);
    return null;
  }
